package tools

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

// scrubber replaces the temporary folders in a result with the names the golden file uses.
func scrubber(base, root string) func(string) string {
	return func(s string) string {
		return strings.ReplaceAll(strings.ReplaceAll(s, root, "<ROOT>"), base, "<BASE>")
	}
}

// supersededByContainment are the golden calls whose Elixir result came from reading outside
// the repository root or through the home folder; the reading tools now refuse them (see
// TestReadContainFaults), so only the refusal is asserted for them.
var supersededByContainment = map[string]bool{
	`read_file {"path":"//a.txt"}`:                               true,
	`read_file {"path":"../kogen-agent-definitely-missing-xyz"}`: true,
	`read_file {"path":"~/kogen-agent-missing-xyz"}`:             true,
	`read_file {"path":"~"}`:                                     true,
	`read_file {"path":"\/a.txt"}`:                               true,
	`list_files {"path":"../x"}`:                                 true,
	`list_files {"path":"/tmp"}`:                                 true,
	`view_image {"path":"~/kogen-missing.png"}`:                  true,
	`search_text {"pattern":"needle","path":"../x"}`:             true,
}

// supersededByLineRange holds the results the golden file records for line ranges that
// read_file now reports instead of reading something else or nothing.
var supersededByLineRange = map[string]string{
	`read_file {"path":"a.txt","start_line":3,"end_line":1}`:                 "error: end_line 1 is before start_line 3",
	`read_file {"path":"a.txt","start_line":"2"}`:                            "error: argument start_line must be an integer",
	`read_file {"path":"a.txt","start_line":2.0}`:                            "error: argument start_line must be an integer",
	`read_file {"path":"a.txt","start_line":1e0,"end_line":2}`:               "error: argument start_line must be an integer",
	`read_file {"path":"a.txt","end_line":2.5}`:                              "error: argument end_line must be an integer",
	`read_file {"path":"a.txt","start_line":99}`:                             "(start_line 99 is past the end of a.txt; line count: 3)",
	`read_file {"path":"a.txt","end_line":0}`:                                "error: end_line 0 is before start_line 1",
	`read_file {"path":"a.txt","end_line":-1}`:                               "error: end_line -1 is before start_line 1",
	`read_file {"path":"a.txt","start_line":123456789012345678901234567890}`: "(start_line 9223372036854775807 is past the end of a.txt; line count: 3)",
	`read_file {"path":"a.txt","start_line":null,"end_line":null}`:           "error: argument start_line must be an integer",
	`read_file {"path":"a.txt","start_line":1E1}`:                            "error: argument start_line must be an integer",
	`read_file {"path":"a.txt","start_line":1e999}`:                          "error: argument start_line is a number too large to represent",
}

// TestToolsMatchTheElixirResults replays every call of the golden file (generated by
// testdata/gen_tools.exs from the Elixir Kogen.Tools) in the same repository and compares
// the results: read_file, write_file (protected path), list_files, search_text, unknown
// tools, argument decoding and view_image, which covers the PNG limits and messages.
func TestToolsMatchTheElixirResults(t *testing.T) {
	t.Parallel()
	g := loadGolden(t)
	base, root := g.build(t)
	scrub := scrubber(base, root)
	tools := newTools(root, g.Tools...)
	tools.Protected = g.Protected

	// Serial subtests replay calls in order against one shared golden repository.
	for i, c := range g.Calls {
		name := fmt.Sprintf("%03d %s %s", i, c.Name, c.Arguments)
		if len(name) > 100 {
			name = name[:100]
		}
		t.Run(name, func(t *testing.T) {
			args := DecodeArguments(strings.ReplaceAll(c.Arguments, "<ROOT>", root))
			out, err := tools.Run(c.Name, args)
			if err != nil {
				t.Fatal(err)
			}
			var wantText string
			if json.Unmarshal(c.Result, &wantText) == nil {
				if out.Typed() {
					t.Fatalf("typed result, want text %q", wantText)
				}
				got := scrub(out.Text)
				if supersededByContainment[c.Name+" "+c.Arguments] {
					if !strings.HasPrefix(got, "error: ") || !strings.Contains(got, "confined to the repository root") {
						t.Errorf("not refused by containment: %q", got)
					}
					return
				}
				if text, ok := supersededByLineRange[c.Name+" "+c.Arguments]; ok {
					wantText = text
				}
				if c.Name == SearchTextTool && c.Arguments == `{"pattern":"a\u0000b"}` {
					wantText = "error: pattern contains a NUL character"
				}
				// The original replay wrote through link.txt to protected a.txt. Its
				// refusal also changes subsequent reads and searches of that file.
				switch i {
				case 96:
					wantText = "refused: a.txt is part of the approved acceptance baseline"
				case 97:
					wantText = "1\tone\n2\ttwo\n3\tthree"
				case 132:
					wantText = strings.Replace(wantText, "a.txt:1:through link", "a.txt:1:one\na.txt:2:two\na.txt:3:three", 1)
				case 133:
					wantText = "a.txt:1:one\na.txt:2:two"
				}
				if got != wantText {
					t.Errorf("result\n got: %q\nwant: %q", got, wantText)
				}
				return
			}
			var want []map[string]string
			if err := json.Unmarshal(c.Result, &want); err != nil {
				t.Fatal(err)
			}
			if !out.Typed() {
				t.Fatalf("text result %q, want typed parts", out.Text)
			}
			if len(out.Parts) != len(want) {
				t.Fatalf("%d parts, want %d", len(out.Parts), len(want))
			}
			for j, p := range out.Parts {
				part := p.(map[string]any)
				for k, wantValue := range want[j] {
					got, _ := part[k].(string)
					if c.Name == ViewImageTool && k == "text" {
						wantValue = strings.Replace(wantValue, "615750f7b5d70fc06ba58ecce4f0e2560c85eec4", "8e01a7661acb9333788e2b9d7b9e3094899371dc", 1)
					}
					if got = scrub(got); got != wantValue {
						t.Errorf("part %d %s\n got: %q\nwant: %q", j, k, got, wantValue)
					}
				}
				if len(part) != len(want[j]) {
					t.Errorf("part %d has keys %v, want %d", j, part, len(want[j]))
				}
			}
		})
	}
}
